def compute(vars):
    value_2018 = vars["v1"]
    value_2019 = vars["v2"]
    difference = value_2019 - value_2018

    return {
        "value": difference,
        "trace": {
            "value_2018": value_2018,
            "value_2019": value_2019,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
